import { Button } from '@refy-design/web';
import { Tooltip } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof Tooltip>, 'label' | 'side' | 'delayMs'> = {
    label: 'Credits roll over',
    side: 'top',
    delayMs: 350,
  };
  return (
    <Tooltip {...args}>
      <Button variant="secondary">Credits</Button>
    </Tooltip>
  );
}

import { Button } from '@refy-design/web';
