import { Button } from '@refy-design/web';
import { Tooltip } from '@refy-design/web';
export function Example() {
  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(2, minmax(0, 120px))',
        gap: '80px 24px',
        placeItems: 'center',
      }}
    >
      {(['top', 'bottom', 'left', 'right'] as const).map((side) => (
        <Tooltip key={side} label={`Side ${side}`} side={side} defaultOpen delayMs={0}>
          <Button variant="secondary">{side}</Button>
        </Tooltip>
      ))}
    </div>
  );
}
